let busqueda = '';
const input = document.querySelector('input');
const salida = document.querySelector('p');

input.addEventListener('input', () => {   // vista -> modelo
  busqueda = input.value;
  salida.textContent = `Buscando: ${busqueda}`; // modelo -> vista
});

import { signal, computed, effect } from '@angular/core';

const precio = signal(25);
const cantidad = signal(1);
const total = computed(() => precio() * cantidad());

effect(() => console.log('Total:', total()));

cantidad.set(3);   // total se recalcula y el effect vuelve a ejecutarse

