let estado = { tipo: 'inicial' };

async function cargarCatalogo() {
  estado = { tipo: 'cargando' };      render();
  try {
    const r = await fetch('/api/productos');
    if (!r.ok) throw new Error(r.status);
    estado = { tipo: 'exito', datos: await r.json() };
  } catch (e) {
    estado = { tipo: 'error', mensaje: 'No se pudo cargar el catálogo' };
  }
  render();
}
